// once, at the app root
<ToastStack fixed position="bottom-right" offset={{ y: 72 }} />

// anywhere in the app
import { toast } from "./components/toast-stack";
const id = toast({
  title: "Invoice archived",
  description: "INV-0411 moved to Archive.",
  tone: "success",
  duration: 8000,
  action: { label: "Undo", onClick: () => restore("INV-0411") },
  onDismiss: (id, reason) => console.log(reason), // "timeout" | "close" | "swipe" | "action" | "dismiss"
});
toast.update(id, { title: "Invoice archived for good" });
toast.dismiss(id);
